[
  {
    "sys_consequence_reasoning": "Spending another $100 might just add to what I've lost",
    "pda_self_consequence_regret": "suspect I'd kick myself for it later"
  },
  {
    "pd_personal_consequence_anxiety": "word may get around that I chase people over money",
    "pd_decision_conflict": "Neither feels settled.",
    "pda_self_consequence_regret": "accepted doing $500 of work for free, which I already regret."
  },
  {
    "sys_consequence_reasoning": "paying $100 to make someone else lose $300 doesn't get me anything back.",
    "pda_self_consequence_regret": "I'm sorry I lost it"
  },
  {
    "sys_fairness_reciprocity": "Letting someone collect for work they didn't do sits wrong with me.",
    "sys_consequence_reasoning": "if I drop another $100 on this and nothing changes for me",
    "pda_self_consequence_regret": "I'll probably regret that too."
  },
  {
    "sys_consequence_reasoning": "A review wouldn't return any of it",
    "pda_self_consequence_regret": "The loss I keep coming back to is mine"
  },
  {
    "pd_decision_conflict": "might feel like standing up for myself, or it might just be $100 spent",
    "pda_self_consequence_regret": "I'm sorry to have lost that bit of faith"
  },
  {
    "sys_fairness_reciprocity": "If nobody ever calls this out, it keeps happening.",
    "sys_consequence_reasoning": "$100 isn't small for me on top of that.",
    "pda_self_consequence_regret": "I already regret the unpaid day"
  },
  {
    "ce_contextual_explanation": "Maybe they had a genuine emergency, maybe they just didn't bother.",
    "pda_self_consequence_regret": "I'm frankly disappointed in how that turned out for me."
  },
  {
    "pd_decision_conflict": "I'm genuinely torn",
    "sys_consequence_reasoning": "The math doesn't help me: $100 out, nothing back.",
    "pda_self_consequence_regret": "I've already regretted losing that $500 more than once"
  },
  {
    "sys_consequence_reasoning": "The review would cost me, cost them, and help nobody's bank account.",
    "pda_self_consequence_regret": "I'll likely look back on this job as a loss either way."
  }
]
